 1	/**
 2	 * Help content tests for the 4 knowledge MCP tools and ledger_get_repository_context.
 3	 *
 4	 * Verifies that TOOL_HELP contains a non-empty string entry for each of the
 5	 * new knowledge tools and the repository context tool so that ledger_help
 6	 * returns useful documentation when agents query any of them.
 7	 */
 8	import { describe, it, expect } from 'vitest';
 9	import { TOOL_HELP } from '../../src/tools/help-content.js';
10	
11	const KNOWLEDGE_TOOL_NAMES = [
12	  'ledger_add_insight',
13	  'ledger_search_insights',
14	  'ledger_list_insights',
15	  'ledger_update_insight',
16	] as const;
17	
18	describe('Knowledge tool help content', () => {
19	  for (const toolName of KNOWLEDGE_TOOL_NAMES) {
20	    it(`TOOL_HELP has a non-empty entry for ${toolName}`, () => {
21	      const helpText = TOOL_HELP[toolName];
22	      expect(helpText, `Missing TOOL_HELP entry for ${toolName}`).toBeDefined();
23	      expect(typeof helpText).toBe('string');
24	      expect(helpText!.trim().length, `TOOL_HELP entry for ${toolName} is empty`).toBeGreaterThan(0);
25	    });
26	
27	    it(`${toolName} help entry includes the tool name as a heading`, () => {
28	      const helpText = TOOL_HELP[toolName]!;
29	      expect(helpText).toContain(`# ${toolName}`);
30	    });
31	  }
32	});
33	
34	describe('ledger_get_repository_context help content', () => {
35	  const toolName = 'ledger_get_repository_context';
36	
37	  it('TOOL_HELP has a non-empty entry for ledger_get_repository_context', () => {
38	    const helpText = TOOL_HELP[toolName];
39	    expect(helpText, `Missing TOOL_HELP entry for ${toolName}`).toBeDefined();
40	    expect(typeof helpText).toBe('string');
41	    expect(helpText!.trim().length, `TOOL_HELP entry for ${toolName} is empty`).toBeGreaterThan(0);
42	  });
43	
44	  it('help entry includes the tool name as a heading', () => {
45	    const helpText = TOOL_HELP[toolName]!;
46	    expect(helpText).toContain(`# ${toolName}`);
47	  });
48	
49	  it('help entry documents the cwd_path parameter', () => {
50	    const helpText = TOOL_HELP[toolName]!;
51	    expect(helpText).toContain('cwd_path');
52	  });
53	
54	  it('help entry documents the repository_name parameter', () => {
55	    const helpText = TOOL_HELP[toolName]!;
56	    expect(helpText).toContain('repository_name');
57	  });
58	
59	  it('help entry documents the include_insights parameter', () => {
60	    const helpText = TOOL_HELP[toolName]!;
61	    expect(helpText).toContain('include_insights');
62	  });
63	
64	  it('help entry documents the max_projects parameter', () => {
65	    const helpText = TOOL_HELP[toolName]!;
66	    expect(helpText).toContain('max_projects');
67	  });
68	
69	  it('help entry describes the response shape fields', () => {
70	    const helpText = TOOL_HELP[toolName]!;
71	    expect(helpText).toContain('repository_name');
72	    expect(helpText).toContain('repository_id');
73	    expect(helpText).toContain('repository_label');
74	    expect(helpText).toContain('total_projects');
75	    expect(helpText).toContain('strategic_vision');
76	    expect(helpText).toContain('projects');
77	    expect(helpText).toContain('relevant_insights');
78	  });
79	
80	  it('help entry documents outcome_summary in the response shape', () => {
81	    const helpText = TOOL_HELP[toolName]!;
82	    expect(helpText).toContain('outcome_summary');
83	  });
84	
85	  it('help entry appears in the overview tool table', () => {
86	    const overviewText = TOOL_HELP['overview']!;
87	    expect(overviewText).toContain(toolName);
88	  });
89	});

 1	import { z } from 'zod';
 2	import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
 3	import { TOOL_HELP } from './help-content.js';
 4	
 5	/**
 6	 * Tool: ledger_help
 7	 *
 8	 * Returns usage documentation, examples, and workflow guidance for the
 9	 * Project Ledger MCP tools. Designed to help agents (especially weaker models)
10	 * understand how to correctly call the tools.
11	 */
12	
13	
14	const HelpSchema = z.object({
15	  tool_name: z
16	    .string()
17	    .optional()
18	    .describe(
19	      'Optional. Specific tool name to get help for (e.g., "ledger_update_work_package_status"). Omit to get the full overview with all tools listed.'
20	    ),
21	});
22	
23	async function help(args: z.infer<typeof HelpSchema>) {
24	  const toolName = args.tool_name?.trim();
25	
26	  // If no tool specified, return overview
27	  if (!toolName) {
28	    return {
29	      content: [
30	        {
31	          type: 'text' as const,
32	          text: TOOL_HELP['overview'],
33	        },
34	      ],
35	    };
36	  }
37	
38	  // Look up specific tool help
39	  const helpText = TOOL_HELP[toolName];
40	
41	  if (helpText) {
42	    return {
43	      content: [
44	        {
45	          type: 'text' as const,
46	          text: helpText,
47	        },
48	      ],
49	    };
50	  }
51	
52	  // Tool not found — return available tools list
53	  const availableTools = Object.keys(TOOL_HELP)
54	    .filter((k) => k !== 'overview')
55	    .join(', ');
56	
57	  return {
58	    content: [
59	      {
60	        type: 'text' as const,
61	        text: `Unknown tool: "${toolName}". Available tools: ${availableTools}. Call ledger_help without tool_name for full overview.`,
62	      },
63	    ],
64	  };
65	}
66	
67	/**
68	 * Register help tool on the MCP server
69	 */
70	export function register(server: McpServer): void {
71	  server.registerTool(
72	    'ledger_help',
73	    {
74	      description: 'Get usage documentation, examples, and required parameters for all ledger tools. Call with no arguments for a full overview, or pass tool_name to get detailed help for a specific tool (e.g., tool_name: "ledger_update_work_package_status"). START HERE if you are unsure how to use the ledger tools.',
75	      inputSchema: HelpSchema.passthrough(),
76	    },
77	    // TODO: remove `as any` cast once the MCP SDK exposes compatible Zod
78	    // passthrough types for registerTool's inputSchema parameter.
79	    // Tracked: https://github.com/modelcontextprotocol/typescript-sdk (MCP SDK typing issue)
80	    help as any
81	  );
82	}

